import{_ as e,o as a,c as i,ah as o}from"./chunks/framework.D4KxWb5R.js";const f=JSON.parse('{"title":"Auticway back-office","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/auticway.md","filePath":"src/en/guide/auticway.md"}'),n={name:"en/guide/auticway.md"};function s(r,t,d,c,u,h){return a(),i("div",null,[...t[0]||(t[0]=[o('<h1 id="auticway-back-office" tabindex="-1">Auticway back-office <a class="header-anchor" href="#auticway-back-office" aria-label="Permalink to &quot;Auticway back-office&quot;">​</a></h1><p>Auticway is M&#39;City&#39;s first product. Its back-office opens with your M&#39;City account: no second password.</p><p>The back-office&#39;s sign-in screens are in French; the labels below are quoted as they appear, with a translation.</p><h2 id="signing-in" tabindex="-1">Signing in <a class="header-anchor" href="#signing-in" aria-label="Permalink to &quot;Signing in&quot;">​</a></h2><ol><li>From your <a href="./desk.html#opening-a-product-back-office">desk</a>, open Auticway, or go to the back-office sign-in page and click <strong>Se connecter avec M&#39;City</strong> (&quot;Sign in with M&#39;City&quot;).</li><li>If you are not signed in to M&#39;City, sign in (with your two-factor authentication).</li><li>You land on the Auticway dashboard.</li></ol><p>On the M&#39;City side you need an active account, the product active and back-office access granted (see <a href="./administration/accounts.html">Accounts</a>). At first sign-in, an Auticway administrator account with the same e-mail address is linked to your M&#39;City account; otherwise an account is created.</p><p>Signing out of M&#39;City also signs you out of Auticway. Disabling your M&#39;City account, or removing your access, closes your Auticway sessions at once.</p><h2 id="what-you-see-there" tabindex="-1">What you see there <a class="header-anchor" href="#what-you-see-there" aria-label="Permalink to &quot;What you see there&quot;">​</a></h2><p>Your M&#39;City position decides your Auticway role. It is recomputed at each sign-in: a change of position takes effect at the next sign-in.</p><table tabindex="0"><thead><tr><th>M&#39;City position</th><th>Auticway role</th><th>Pages</th></tr></thead><tbody><tr><td>CEO, Product Operations</td><td>admin-mcity</td><td>All, except roles and sessions (kept for the Auticway super-administrator)</td></tr><tr><td>Support head, Support L2</td><td>mcity-support</td><td>Dashboard, users (edit), providers, offers, bookings, reviews, alerts, broadcasts, content</td></tr><tr><td>Support L1</td><td>mcity-support-n1</td><td>Dashboard, bookings, reviews, alerts, users (view only)</td></tr><tr><td>Finance</td><td>mcity-finance</td><td>Dashboard, payments, accounting, bookings</td></tr><tr><td>HR &amp; Legal</td><td>mcity-hr</td><td>Dashboard, users (edit, to disable an account)</td></tr></tbody></table><p>A restricted role edits only customer and provider accounts, never administration accounts.</p><h2 id="refusal-messages" tabindex="-1">Refusal messages <a class="header-anchor" href="#refusal-messages" aria-label="Permalink to &quot;Refusal messages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Message</th><th>What to do</th></tr></thead><tbody><tr><td>« Votre poste M&#39;City ne donne pas accès au back-office Auticway. Contactez votre administrateur M&#39;City. » (Your M&#39;City position gives no access to the Auticway back-office.)</td><td>Your account has no recognised position: ask the administrator to assign one.</td></tr><tr><td>« Ce compte est désactivé. » (This account is disabled.)</td><td>The Auticway account is disabled: contact the Auticway administrator.</td></tr><tr><td>« Cette adresse e-mail appartient à un compte qui n&#39;est pas un compte administrateur. » (This e-mail address belongs to an account that is not an administrator account.)</td><td>The address belongs to an Auticway customer or provider account, or to an account already linked to another M&#39;City account: ask the Auticway administrator to resolve it.</td></tr><tr><td>Back on M&#39;City with an access refusal</td><td>Back-office access is not granted to you, or the product is inactive: check with your head of unit.</td></tr></tbody></table><h2 id="back-office-notifications" tabindex="-1">Back-office notifications <a class="header-anchor" href="#back-office-notifications" aria-label="Permalink to &quot;Back-office notifications&quot;">​</a></h2><p>The Auticway back-office bell shows the events to handle, depending on your pages. It opens the full list and the <strong>Préférences</strong> (preferences), where you choose, for each event, the in-back-office notification and the e-mail. Notifications are deleted after 90 days.</p><table tabindex="0"><thead><tr><th>Event</th><th>Page needed</th><th>E-mail by default</th></tr></thead><tbody><tr><td>Provider to verify</td><td>Providers</td><td>Yes</td></tr><tr><td>Pending booking</td><td>Bookings</td><td>No</td></tr><tr><td>Alert report</td><td>Alerts</td><td>Yes</td></tr><tr><td>Failed payment</td><td>Payments</td><td>Yes</td></tr><tr><td>Failed accounting export</td><td>Accounting</td><td>Yes</td></tr></tbody></table>',16)])])}const y=e(n,[["render",s]]);export{f as __pageData,y as default};
